def indexedJLDualEquiv {Λ : Type} {B : Set (Set Point)} (hB : AlmostDisjoint B) (hInf : B.Infinite)
    (e : Λ ≃ B) : (JL B →L[ℝ] ℝ) ≃ₗᵢ[ℝ] lp (fun _ : IndexedAtom Λ => ℝ) 1 :=
  (jlDualEquiv hB hInf).trans (lpOneReindex (compactumAtomEquiv e))

